use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // 1. Clock: read the wall-clock time once.
        let seconds = wall_clock::now().seconds;

        // 2. HTTP: one fetch of the given feed.
        // A failure to fetch, such as a timeout, an error status, or an
        // oversize body, comes back as a value. Count it as zero characters.
        // A host outside the allowlist traps at the boundary. This node does
        // not try to work around that.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = body.chars().count();
                if n > u32::MAX as usize {
                    u32::MAX
                } else {
                    n as u32
                }
            }
            Err(_) => 0,
        };

        // 3. Notifier: report the heartbeat on the digest channel.
        let message = format!(
            "heartbeat: t={} feed={} fetched={} chars",
            seconds, feed_url, fetched
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // The contract requires `notified == true`. If the channel never
        // accepts the message, trap. Reporting a false claim would be worse.
        if !notified {
            panic!("heartbeat: notifier refused the notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
